<?php

declare(strict_types=1);
namespace App\Form\Type\Quote; use App\Entity\Quote\QuoteRequest; use Symfony\Component\Form\AbstractType; use Symfony\Component\Form\Extension\Core\Type\{CheckboxType,CountryType,DateType,HiddenType,TextareaType}; use Symfony\Component\Form\FormBuilderInterface; use Symfony\Component\OptionsResolver\OptionsResolver; use Symfony\Component\Validator\Constraints\IsTrue;
final class QuoteRequestType extends AbstractType {public function buildForm(FormBuilderInterface $b,array $o):void{$b->add('company')->add('contactName')->add('email')->add('phone')->add('customerNumber')->add('street')->add('houseNumber')->add('postalCode')->add('city')->add('countryCode',CountryType::class)->add('projectReference')->add('requestedDeliveryDate',DateType::class,['widget'=>'single_text','required'=>false])->add('customerPurchaseOrderNumber')->add('message',TextareaType::class,['required'=>false,'attr'=>['rows'=>6,'maxlength'=>5000,'placeholder'=>'cardnext.quote.form.message_placeholder']])->add('needsAdvice',CheckboxType::class,['required'=>false])->add('needsCompatibilityCheck',CheckboxType::class,['required'=>false])->add('privacyConsent',CheckboxType::class,['mapped'=>false,'constraints'=>[new IsTrue(message:'cardnext.quote.validation.privacy')]])->add('website',HiddenType::class,['mapped'=>false,'required'=>false]);}public function configureOptions(OptionsResolver $r):void{$r->setDefaults(['data_class'=>QuoteRequest::class,'csrf_token_id'=>'cardnext_quote_submit']);}}
